"""Build the self-contained, 10-slide HTML used for browser PDF export."""
from pathlib import Path
from base64 import b64encode

ROOT = Path(__file__).resolve().parents[2]
APP = ROOT / 'otula'
SHOTS = APP / 'materialy/zrzuty-21-11'
PUBLIC = 'https://otula-dla-rodziny.etherealdaffodil4.chatgpt.site'
BRIEF = 'https://mudnibfuppwadjkynscc.supabase.co/storage/v1/object/public/task-files/057d36b5-cb92-4062-9393-983cb8a96088/files/d02b6603-486b-474e-837f-3ada06d12bee.pdf'

def data(path):
    suffix = path.suffix.lower()
    mime = {'.svg':'image/svg+xml','.webp':'image/webp','.png':'image/png','.ttf':'font/ttf'}[suffix]
    return 'data:'+mime+';base64,'+b64encode(path.read_bytes()).decode()

def img(name, cls='', alt=''):
    path = SHOTS / name if (SHOTS / name).exists() else APP / 'dist/assets' / name
    return f'<img class="{cls}" src="{data(path)}" alt="{alt}">'

slides = []
def slide(title, body, note, cls=''):
    n = len(slides)+1
    heading = f'<h2>{title}</h2>' if title else ''
    slides.append(f'<section class="slide {cls}" aria-label="Slajd {n}">{heading}<div class="content">{body}</div><footer><span>Otula</span><span>{n} / 10</span></footer></section><aside class="notes"><h3>Notatki do slajdu {n}</h3>{note}</aside>')

