 solid #dfcbc7;padding-top:25px}.architecture-bottom p{font-size:24px}.criteria{width:100%;border-collapse:collapse;font-size:23px}.criteria th{text-align:left;background:#f6e3eb;font-size:20px}.criteria th,.criteria td{padding:14px 18px;border-bottom:1px solid #e9d9d2}.criteria td:nth-child(2){font-weight:700;color:#82445b}.criteria th:nth-child(2){width:95px}.evidence{display:flex;align-items:center;gap:22px;padding:24px 0 18px}.evidence strong{font-family:'DM Serif Text',serif;font-size:40px;font-weight:400;color:#814960}.evidence strong:nth-child(3){margin-left:46px}.evidence span{font-size:19px}.final-layout{display:grid;grid-template-columns:1fr 1fr;gap:60px}.demo-link{font-size:26px}.demo-link a{text-decoration-thickness:1px;text-underline-offset:5px}.disclosure{background:#f8e6ed;border-radius:25px;padding:28px 32px}.disclosure p{font-size:23px}.disclosure .small{font-size:18px}.notes{max-width:1100px;background:#fff;margin:0 auto 30px;padding:30px;font-size:20px}.toolbar{max-width:1280px;margin:24px auto;font-size:18px}.toolbar button{font:inherit;padding:12px 20px;border:0;background:#773f56;color:#fff;border-radius:8px;cursor:pointer}@page{size:13.333333in 7.5in;margin:0}@media print{html,body{background:white}.slide{margin:0;break-after:page;page-break-after:always}.slide:last-of-type{break-after:auto;page-break-after:auto}.toolbar,.notes{display:none}}
