fonts = ''.join(f"@font-face{{font-family:'{family}';src:url({data(APP/'dist/assets'/file)});font-weight:{weight};font-style:normal}}" for family,file,weight in [('DM Sans','dm-sans.ttf','100 900'),('DM Serif Text','dm-serif-text.ttf','400')])
html = '<!doctype html><html lang="pl"><meta charset="utf-8"><title>Otula — prezentacja dla jury</title><style>'+fonts+css+'</style><body><div class="toolbar"><button onclick="window.print()">Drukuj slajdy / PDF</button> 10 slajdów · notatki pozostają poza wydrukiem</div>'+''.join(slides)+'</body></html>'
for target in [ROOT/'Otula-slajdy-i-notatki.html', APP/'materialy/Otula-slajdy-i-notatki.html']:
    target.write_text(html,encoding='utf-8')
print('Zapisano 10 slajdów HTML z osadzonymi zrzutami, fontami i notatkami.')
